import React from "react";
import { useLocation } from "react-router-dom";
import "/AdoptionAnimalData.css";
const AdoptionAnimalData = () => {
  const location = useLocation();
  const {
    name,
    age,
    type,
    location: petLocation,
    description,
    image,
  } = location.state;

  return (
    <div className="page-wrapper">
      <main className="main">
        <div className="content-wrapper">
          <div className="pet-image-container">
            <img src={image} alt={name} className="pet-image" />
          </div>

          <div className="pet-info">
            <h2 className="pet-name">{name}</h2>
            <p>
              <strong>Age:</strong> {age} years
            </p>
            <p>
              <strong>Type:</strong> {type}
            </p>
            <p>
              <strong>Location:</strong> {petLocation}
            </p>
            <p className="pet-description">{description}</p>
            <h3>Adopt {name}</h3>
            <form className="email-form">
              <label htmlFor="email">Enter your email:</label>
              <input
                type="email"
                id="email"
                name="email"
                placeholder="example@mail.com"
                required
              />
              <button type="submit" className="adopt-button">
                Adopt Me!
              </button>
            </form>
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdoptionAnimalData;
